@using sv_0d4a8e25e2dc4a448cb5fe843059766c.Services

<div class="card">
    <div class="card-body">
        <h4 class="card-title mb-4">Security Settings</h4>

        <ChangePasswordPanel OnChangePassword="OnChangePassword" />

        <div class="card mb-3">
            <div class="card-body">
                <div class="d-flex justify-content-between align-items-center">
                    <div>
                        <strong>🛡️ Two-Factor Authentication</strong>
                        <br />
                        <small class="text-muted">
                            Status:
                            @if (Security.TwoFactorEnabled)
                            {
                                <span class="badge bg-success">Enabled</span>
                            }
                            else
                            {
                                <span class="badge bg-secondary">Disabled</span>
                            }
                        </small>
                    </div>
                    <div class="form-check form-switch">
                        <input class="form-check-input" type="checkbox" checked="@Security.TwoFactorEnabled" disabled
                               title="Contact admin to change 2FA status" />
                    </div>
                </div>
                @if (Security.LastPasswordChange.HasValue)
                {
                    <small class="text-muted d-block mt-2">
                        Last password change: @Security.LastPasswordChange.Value.ToString("MMMM dd, yyyy")
                    </small>
                }
            </div>
        </div>

        <div class="card">
            <div class="card-body">
                <h6>📱 Active Sessions</h6>
                <div class="table-responsive">
                    <table class="table table-hover mb-0">
                        <thead>
                            <tr>
                                <th>Device</th>
                                <th>Location</th>
                                <th>Last Active</th>
                                <th></th>
                            </tr>
                        </thead>
                        <tbody>
                            @foreach (var session in Security.Sessions)
                            {
                                var isCurrent = session.Id == Security.Sessions.FirstOrDefault()?.Id;
                                <tr>
                                    <td>
                                        @session.Device
                                        @if (isCurrent) { <span class="badge bg-primary ms-1">Current</span> }
                                    </td>
                                    <td>@session.Location</td>
                                    <td>@FormatLastActive(session.LastActive)</td>
                                    <td>
                                        @if (!isCurrent)
                                        {
                                            <button class="btn btn-outline-danger btn-sm"
                                                    @onclick="() => PromptRevoke(session)">
                                                Revoke
                                            </button>
                                        }
                                    </td>
                                </tr>
                            }
                        </tbody>
                    </table>
                </div>
            </div>
        </div>

        @* Revoke confirmation dialog *@
        @if (_sessionToRevoke is not null)
        {
            <div class="modal d-block" tabindex="-1" style="background:rgba(0,0,0,0.5)">
                <div class="modal-dialog modal-dialog-centered">
                    <div class="modal-content">
                        <div class="modal-header">
                            <h5 class="modal-title">Revoke Session</h5>
                            <button type="button" class="btn-close" @onclick="CancelRevoke"></button>
                        </div>
                        <div class="modal-body">
                            <p>Are you sure you want to revoke the session on <strong>@_sessionToRevoke.Device</strong> from <strong>@_sessionToRevoke.Location</strong>?</p>
                            <p class="text-muted small">This will sign out that device immediately.</p>
                        </div>
                        <div class="modal-footer">
                            <button class="btn btn-secondary" @onclick="CancelRevoke">Cancel</button>
                            <button class="btn btn-danger" @onclick="ConfirmRevokeAsync" disabled="@_revoking">
                                @if (_revoking) { <span class="spinner-border spinner-border-sm me-1"></span> }
                                Revoke Session
                            </button>
                        </div>
                    </div>
                </div>
            </div>
        }
    </div>
</div>

@code {
    [Parameter, EditorRequired] public SecuritySettings Security { get; set; } = default!;
    [Parameter, EditorRequired] public EventCallback<(string Current, string New)> OnChangePassword { get; set; }
    [Parameter, EditorRequired] public EventCallback<string> OnRevokeSession { get; set; }

    private ActiveSession? _sessionToRevoke;
    private bool _revoking;

    private void PromptRevoke(ActiveSession session) => _sessionToRevoke = session;
    private void CancelRevoke() => _sessionToRevoke = null;

    private async Task ConfirmRevokeAsync()
    {
        if (_sessionToRevoke is null) return;
        _revoking = true;
        await OnRevokeSession.InvokeAsync(_sessionToRevoke.Id);
        _revoking = false;
        _sessionToRevoke = null;
    }

    private static string FormatLastActive(DateTime dt)
    {
        var diff = DateTime.UtcNow - dt;
        if (diff.TotalMinutes < 1) return "Just now";
        if (diff.TotalMinutes < 60) return $"{(int)diff.TotalMinutes}m ago";
        if (diff.TotalHours < 24) return $"{(int)diff.TotalHours}h ago";
        return $"{(int)diff.TotalDays}d ago";
    }
}

@using sv_0d4a8e25e2dc4a448cb5fe843059766c.Services

<div class="card">
    <div class="card-body">
        <h4 class="card-title mb-4">Appearance Settings</h4>

        <div class="row">
            <div class="col-md-6">
                <div class="mb-4">
                    <h6 class="text-muted mb-2">Theme</h6>
                    @foreach (var theme in new[] { "Light", "Dark", "System" })
                    {
                        <div class="form-check">
                            <input class="form-check-input" type="radio" name="theme" id="theme-@theme"
                                   value="@theme" checked="@(Theme == theme)"
                                   @onchange="() => Theme = theme" />
                            <label class="form-check-label" for="theme-@theme">@theme</label>
                        </div>
                    }
                </div>

                <div class="mb-4">
                    <h6 class="text-muted mb-2">Font Size</h6>
                    @foreach (var size in new[] { "Small", "Medium", "Large" })
                    {
                        <div class="form-check">
                            <input class="form-check-input" type="radio" name="fontSize" id="fs-@size"
                                   value="@size" checked="@(FontSize == size)"
                                   @onchange="() => FontSize = size" />
                            <label class="form-check-label" for="fs-@size">@size</label>
                        </div>
                    }
                </div>

                <div class="mb-4">
                    <h6 class="text-muted mb-2">Language</h6>
                    <select class="form-select" @bind="Language">
                        <option value="English">English</option>
                        <option value="Spanish">Spanish</option>
                        <option value="French">French</option>
                        <option value="German">German</option>
                        <option value="Japanese">Japanese</option>
                        <option value="Chinese">Chinese</option>
                    </select>
                </div>

                <div class="mb-4">
                    <h6 class="text-muted mb-2">Compact Mode</h6>
                    <div class="form-check form-switch">
                        <input class="form-check-input" type="checkbox" id="compactMode" @bind="CompactMode" />
                        <label class="form-check-label" for="compactMode">
                            Reduce spacing and padding
                        </label>
                    </div>
                </div>
            </div>

            <div class="col-md-6">
                <h6 class="text-muted mb-2">Live Preview</h6>
                <div class="border rounded @PreviewClasses" style="@PreviewStyles">
                    <div class="@(CompactMode ? "p-2" : "p-3")" style="border-bottom:1px solid currentColor; opacity:0.3;">
                        <strong>Header Bar</strong>
                    </div>
                    <div class="@(CompactMode ? "p-2" : "p-3")">
                        <h6 style="@FontSizeStyle">Sample Heading</h6>
                        <p style="@FontSizeStyle" class="mb-2">
                            This is how your content will look with the selected appearance settings.
                        </p>
                        <button class="btn @PreviewButtonClass btn-sm">Sample Button</button>
                        <span class="badge @PreviewBadgeClass ms-2">Badge</span>
                    </div>
                    <div class="@(CompactMode ? "p-2" : "p-3")" style="border-top:1px solid currentColor; opacity:0.3;">
                        <small>Footer — @Language</small>
                    </div>
                </div>
            </div>
        </div>

        @if (!string.IsNullOrEmpty(_statusMessage))
        {
            <div class="alert alert-success alert-dismissible fade show mt-3" role="alert">
                @_statusMessage
                <button type="button" class="btn-close" @onclick="() => _statusMessage = null"></button>
            </div>
        }

        <button class="btn btn-primary mt-3" @onclick="SaveAsync" disabled="@_saving">
            @if (_saving) { <span class="spinner-border spinner-border-sm me-1"></span> }
            Save
        </button>
    </div>
</div>

@code {
    [Parameter, EditorRequired] public AppearanceSettings Settings { get; set; } = default!;
    [Parameter, EditorRequired] public EventCallback<AppearanceSettings> OnSave { get; set; }

    private string Theme = "Light";
    private string FontSize = "Medium";
    private string Language = "English";
    private bool CompactMode;
    private string? _statusMessage;
    private bool _saving;

    protected override void OnParametersSet()
    {
        if (!_saving)
        {
            Theme = Settings.Theme;
            FontSize = Settings.FontSize;
            Language = Settings.Language;
            CompactMode = Settings.CompactMode;
        }
    }

    private async Task SaveAsync()
    {
        _saving = true;
        _statusMessage = null;
        var updated = new AppearanceSettings(Theme, FontSize, Language, CompactMode);
        await OnSave.InvokeAsync(updated);
        _statusMessage = "Appearance settings saved!";
        _saving = false;
    }

    private string PreviewClasses => Theme switch
    {
        "Dark" => "text-light",
        _ => "text-dark"
    };

    private string PreviewStyles
    {
        get
        {
            var bg = Theme switch
            {
                "Dark" => "background:#1e1e1e; color:#e0e0e0;",
                "System" => "background:#f0f0f0; color:#333;",
                _ => "background:#ffffff; color:#212529;"
            };
            return bg + " min-height:180px; transition: all 0.3s ease;";
        }
    }

    private string FontSizeStyle => FontSize switch
    {
        "Small" => "font-size:0.85rem;",
        "Large" => "font-size:1.15rem;",
        _ => "font-size:1rem;"
    };

    private string PreviewButtonClass => Theme == "Dark" ? "btn-outline-light" : "btn-primary";
    private string PreviewBadgeClass => Theme == "Dark" ? "bg-light text-dark" : "bg-primary";
}

@page "/settings"
@rendermode InteractiveServer
@using sv_0d4a8e25e2dc4a448cb5fe843059766c.Services
@inject ISettingsService SettingsService

<PageTitle>Settings</PageTitle>

<h2 class="mb-4">⚙️ Settings</h2>

@if (_loading)
{
    <div class="d-flex justify-content-center py-5">
        <div class="spinner-border" role="status">
            <span class="visually-hidden">Loading...</span>
        </div>
    </div>
}
else
{
    <div class="row">
        <div class="col-md-3 col-lg-2 mb-3">
            <SettingsSidebar ActiveSection="@_activeSection" OnSectionChanged="s => _activeSection = s" />
        </div>
        <div class="col-md-9 col-lg-10">
            @switch (_activeSection)
            {
                case "Profile":
                    <ProfileSection Profile="@_profile!" OnSave="SaveProfileAsync" />
                    break;
                case "Notifications":
                    <NotificationsSection Prefs="@_notificationPrefs!" OnSave="SaveNotificationPrefsAsync"
                                          AllChannels="@_allChannels" />
                    break;
                case "Security":
                    <SecuritySection Security="@_security!" OnChangePassword="ChangePasswordAsync"
                                     OnRevokeSession="RevokeSessionAsync" />
                    break;
                case "Appearance":
                    <AppearanceSection Settings="@_appearance!" OnSave="SaveAppearanceAsync" />
                    break;
            }
        </div>
    </div>
}

@code {
    private string _activeSection = "Profile";
    private bool _loading = true;

    private UserProfile? _profile;
    private NotificationPrefs? _notificationPrefs;
    private SecuritySettings? _security;
    private AppearanceSettings? _appearance;
    private List<string> _allChannels = MockSettingsService.AllChannels;

    protected override async Task OnInitializedAsync()
    {
        _profile = await SettingsService.GetProfileAsync();
        _notificationPrefs = await SettingsService.GetNotificationPrefsAsync();
        _security = await SettingsService.GetSecuritySettingsAsync();
        _appearance = await SettingsService.GetAppearanceAsync();
        _loading = false;
    }

    private async Task SaveProfileAsync(UserProfile profile)
    {
        await SettingsService.SaveProfileAsync(profile);
        _profile = await SettingsService.GetProfileAsync();
    }

    private async Task SaveNotificationPrefsAsync(NotificationPrefs prefs)
    {
        await SettingsService.SaveNotificationPrefsAsync(prefs);
        _notificationPrefs = await SettingsService.GetNotificationPrefsAsync();
    }

    private async Task ChangePasswordAsync((string Current, string New) args)
    {
        await SettingsService.ChangePasswordAsync(args.Current, args.New);
        _security = await SettingsService.GetSecuritySettingsAsync();
    }

    private async Task RevokeSessionAsync(string sessionId)
    {
        await SettingsService.RevokeSessionAsync(sessionId);
        _security = await SettingsService.GetSecuritySettingsAsync();
    }

